using System.Collections.Generic;
using UnityEngine;
namespace GreyHarbor {
 public sealed partial class RaidGame {
  public bool CanBindItem337(ItemArea area,ItemStack item)=>QuickBindingAllowed329&&QuickSlots329.CarriedArea(area)&&item!=null&&item.Identified&&item.Count>0&&QuickSlots329.Supports(item.Kind);
  public bool CanSplitItem337(ItemArea area,ItemStack item)=>!CampLocked&&!Paused&&Access(area)&&!CorpseSource325(area)&&item!=null&&item.Count>1&&InventoryFor(area)!=null&&InventoryFor(area).StackLimit(item.Kind)>1;
  public bool CanDropItem337(ItemArea area,ItemStack item)=>!CampLocked&&!Paused&&Access(area)&&item!=null&&!(area==ItemArea.RigEquipment&&Chest.Slots.Count>0)&&!(area==ItemArea.PackEquipment&&Bag.Slots.Count>0)&&(!CorpseLoot325.IsArea(area)||CorpseContentEmpty325(area,false));
  public bool CanMenuUse337(ItemArea area,ItemStack item)=>!CampLocked&&!Paused&&item!=null&&!AmmoRules270.IsAmmo(item.Kind)&&CanUse(area,item)&&(!ConsumableRules.IsRepair(item.Kind)||ReloadTime<=0&&RepairTime<=0&&HealTime<=0);
 }
 public sealed partial class RaidUI {
  bool quickBind337;
  internal List<string> ItemMenuActions337(){var item=Selected();var actions=new List<string>();if(item==null)return actions;if(G.CanMenuUse337(selectedArea,item))actions.Add("使用");if(G.CanBindItem337(selectedArea,item))actions.Add("绑定");if(G.CanSplitItem337(selectedArea,item))actions.Add("分开");if(G.CanDropItem337(selectedArea,item))actions.Add("丢弃");return actions;}
  internal List<string> DetailActions337(ItemStack item){var a=new List<string>();if(!item.Identified||G.CampLocked)return a;if(WeaponRules279.IsWeapon(item.Kind)){if(selectedArea==ItemArea.Weapon?G.Magazine>0:item.Loaded314>0)a.Add("卸下弹药");a.Add("枪械改装");}if(RepairAvailable())a.Add("维修 · "+ArmorBalance.RepairPrice(item)+" 金币");if(AmmoRules270.IsAmmo(item.Kind)&&G.CanUse(selectedArea,item))a.Add("装入当前武器");return a;}
  string BoundKeys337(ItemStack item){string keys="";for(int i=0;i<5;i++)if(G.QuickSlotKind329(i)==item.Kind)keys+=(keys.Length==0?"":"、")+(i+3);return keys.Length==0?"未绑定":"已绑定："+keys;}
  float CompactOffset337(ItemStack item)=>item!=null&&(AmmoRules270.IsAmmo(item.Kind)||ConsumableRules.IsRepair(item.Kind))?44:0;
  float DetailHeight337(ItemStack item)=>(G.CanBindItem337(selectedArea,item)?330:248+DetailActions337(item).Count*38)-CompactOffset337(item);
  Rect ItemPopupRect337(){var item=Selected();float width=splitOpen?330:context?248:340;float height=splitOpen?234:context?58+Mathf.Max(1,ItemMenuActions337().Count)*38+(quickBind337?60:0):item==null?248:DetailHeight337(item);return new Rect(Mathf.Clamp(popupPos.x,16,1584-width),Mathf.Clamp(popupPos.y,94,850-height),width,height);}
  Rect MenuRow337(Rect r,int index)=>new Rect(r.x+10,r.y+47+index*38,r.width-20,32);
  internal Rect BindingButton337(int index){var r=PopupRect();float y=context?r.y+47+ItemMenuActions337().Count*38+26:r.y+259-CompactOffset337(Selected());float width=(r.width-28-24)/5;return new Rect(r.x+14+index*(width+6),y,width,36);}
  void DrawBindings337(Rect r,ItemStack item,bool compact){float y=compact?r.y+47+ItemMenuActions337().Count*38:r.y+228-CompactOffset337(item);Label(r.x+14,y,r.width-28,24,BoundKeys337(item),14,mint);for(int i=0;i<5;i++)PanelButton(BindingButton337(i),(i+3).ToString(),G.QuickSlotKind329(i)==item.Kind);if(!compact)Label(r.x+14,r.y+301-CompactOffset337(item),r.width-28,20,"点击数字或按 3–7 绑定",13,muted);}
  // Handle popup clicks before grid selection. No event can pass through a popup to the grid.
  bool HandlePopupInput337(Event ev){if(!tooltip&&!context||splitOpen)return false;var r=PopupRect();if(!r.Contains(ev.mousePosition))return false;if(ev.type!=EventType.MouseDown&&ev.type!=EventType.MouseUp&&ev.type!=EventType.ScrollWheel)return false;if(ev.type==EventType.MouseDown&&ev.button==0){var item=Selected();if(item!=null){if(G.CanBindItem337(selectedArea,item)&&(!context||quickBind337)){for(int i=0;i<5;i++)if(BindingButton337(i).Contains(ev.mousePosition)){G.BindQuickSlot329(i,selectedArea,item.Cell);ev.Use();return true;}}
   if(context){var actions=ItemMenuActions337();for(int i=0;i<actions.Count;i++)if(MenuRow337(r,i).Contains(ev.mousePosition)){RunMenuAction337(actions[i],item);break;}}else{var actions=DetailActions337(item);for(int i=0;i<actions.Count;i++)if(new Rect(r.x+14,r.y+241-CompactOffset337(item)+i*38,r.width-28,32).Contains(ev.mousePosition)){RunDetailAction337(actions[i],item);break;}}}}ev.Use();return true;}
  void RunMenuAction337(string action,ItemStack item){switch(action){case "使用":G.UseItem(selectedArea,item.Cell);ClearItemUI();break;case "绑定":quickBind337=!quickBind337;break;case "分开":context=false;quickBind337=false;splitOpen=true;splitText=Mathf.Max(1,item.Count/2).ToString();break;case "丢弃":G.DropItem(selectedArea,item.Cell);ClearItemUI();break;}}
  void RunDetailAction337(string action,ItemStack item){if(action=="枪械改装"){OpenMod30();return;}if(action=="卸下弹药"){if(G.Phase==GamePhase.Base)G.UnloadGun314(selectedArea,Mathf.Max(0,item.Cell));else G.UnloadCarriedGun314(selectedArea,Mathf.Max(0,item.Cell));}else if(action=="装入当前武器")G.UseItem(selectedArea,item.Cell);else G.RepairAtCamp(selectedArea,item.Cell);ClearItemUI();}
  void DrawContext337(Rect r,ItemStack item){var actions=ItemMenuActions337();for(int i=0;i<actions.Count;i++)PanelButton(MenuRow337(r,i),actions[i]=="绑定"?"绑定  "+(quickBind337?"−":"＋"):actions[i],actions[i]=="绑定"&&quickBind337);if(actions.Count==0)Label(r.x+14,r.y+49,r.width-28,25,"暂无可用操作",14,muted);if(quickBind337&&G.CanBindItem337(selectedArea,item))DrawBindings337(r,item,true);}
  string CompactDescription337(ItemStack item){if(AmmoRules270.IsAmmo(item.Kind)){string caliber=WeaponRules279.AmmoCaliber(item.Kind)==AmmoCaliber279.NineMM?"9×19":WeaponRules279.AmmoCaliber(item.Kind)==AmmoCaliber279.Five56?"5.56×45":WeaponRules279.AmmoCaliber(item.Kind)==AmmoCaliber279.Gauge12?"12号":"7.62×39";string guns=caliber=="9×19"?"MP5 / 短剑":caliber=="5.56×45"?"AR-16":caliber=="12号"?"SG12":"AK / SKS";return caliber+" · 适用 "+guns+"\n随身 "+(caliber=="12号"?50:100)+" 发/格 · 仓库 300 发/格";}
   if(ConsumableRules.IsRepair(item.Kind))return "每次最多修复 "+ConsumableRules.RepairBase(item.Kind)+" 点 · 使用 4 秒\n只扣实际用量，受击中断不消耗。";
   if(WeaponRules279.IsWeapon(item.Kind))return ModRules30.Describe(item);return (Certification319.Collection(item.Kind)?CertificationText319(item)+"\n收藏品不能带入战局。\n":"")+RaidInventory.Use(item.Kind);}
  void DrawDetails337(Rect r,ItemStack item){float weight=CarryWeight320.ItemGrams(item,null,G.Equipped,G.Magazine,G.MagazineAmmo)/1000f;string meta=ConsumableRules.IsRepair(item.Kind)?"维修点 "+RepairKit320.Remaining(item).ToString("0.#")+" / "+RepairKit320.Capacity(item.Kind).ToString("0"):ArmorBalance.Defensive(item.Kind)?"护甲 "+item.ArmorPoints.ToString("0.#")+" / "+ArmorBalance.Max(item.Kind):KeyRules2760.IsKey(item.Kind)?"剩余 "+KeyRules2760.Remaining(item)+" / 4 次":"数量 "+item.Count;Label(r.x+14,r.y+49,r.width-28,23,meta+" · "+weight.ToString("0.##")+" kg",14,muted);WrappedLabel(new Rect(r.x+14,r.y+86,r.width-28,108-CompactOffset337(item)),CompactDescription337(item),15,white);Label(r.x+14,r.y+201-CompactOffset337(item),r.width-28,22,"出售单价 "+RaidInventory.Value(item)+" 金币",14,gold);
   if(G.CanBindItem337(selectedArea,item))DrawBindings337(r,item,false);else{var actions=DetailActions337(item);for(int i=0;i<actions.Count;i++)PanelButton(new Rect(r.x+14,r.y+241-CompactOffset337(item)+i*38,r.width-28,32),actions[i]);}}
  internal void QAOpenItem337(ItemArea area,int cell,bool menu,Vector2 position){ClearItemUI();selectedArea=area;selectedId=G.ItemAt(area,cell)?.Id;context=menu;tooltip=!menu;popupPos=position;}
  internal Rect QAPopup337=>PopupRect();
 }
}
